#[derive(Debug)]
pub struct Interval {
    pub min: f64,
    pub max: f64,
}

impl Interval {
    // Construct a new interval and ensure min < max
    pub fn new(min: f64, max: f64) -> Self {
        assert!(min < max, "Interval minimum must be strictly less than maximum");
        Interval { min, max }
    }
}

#[derive(Debug)]
pub struct ChebyshevPoly {
    pub coef: Vec<i32>,   // coefficients as i32
    pub domain: Interval, // domain interval [min, max]
    pub window: Interval, // window interval [min, max]
}

/// Construct a Chebyshev polynomial descriptor from a vector of i8 coefficients:
/// - coef converted to i32 (preserving order and length)
/// - domain interval set to [-1, 1] (valid interval)
/// - window interval set to [-1, 1] (valid interval)
///
/// # Panics
/// If coef is empty (though problem states input size is positive, so no empty input).
pub fn chebyshev(coef: Vec<i8>) -> ChebyshevPoly {
    assert!(!coef.is_empty(), "Input coefficients vector must be non-empty");

    // Convert coefficients from i8 to i32, preserving order
    let coef_i32: Vec<i32> = coef.into_iter().map(|c| c as i32).collect();

    // Default domain and window intervals [-1, 1]
    let domain = Interval::new(-1.0, 1.0);
    let window = Interval::new(-1.0, 1.0);

    ChebyshevPoly {
        coef: coef_i32,
        domain,
        window,
    }
}